typedef struct{char*d,*repo,*src,*file;char old[65];size_t refs,objs;} CFix;
static TestProc cr_init(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc cr_snap_env(const char*r,const char*s,const char*ts,const char*const env[]){const char*a[]={"./darc","--repo",r,"snapshot","create",s,"--timestamp",ts,NULL};return test_exec(a,env);}
static TestProc cr_verify(const char*r,bool repair){const char*a[10];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;a[n++]="verify";a[n++]="--level";a[n++]="scrub";if(repair)a[n++]="--repair";a[n]=NULL;return test_exec(a,NULL);}
static TestProc cr_index(const char*r){const char*a[]={"./darc","--repo",r,"index","rebuild",NULL};return test_exec(a,NULL);}
static TestProc cr_gc(const char*r,const char*ck){const char*a[]={"./darc","--repo",r,"gc","--repack-parity",NULL};char ev[128];const char*env[2]={NULL,NULL};if(ck){snprintf(ev,sizeof ev,"DARC_TEST_CRASH_CHECKPOINT=%s",ck);env[0]=ev;}return test_exec(a,ck?env:NULL);}
static TestProc cr_del(const char*r,const char*id){const char*a[]={"./darc","--repo",r,"snapshot","delete",id,"--yes",NULL};return test_exec(a,NULL);}
static size_t refs_count(const char*r){char*p=test_path(r,"refs/snapshots");DIR*d=p?opendir(p):NULL;size_t n=0;if(d){struct dirent*e;while((e=readdir(d)))if(e->d_name[0]!='.')n++;closedir(d);}free(p);return n;}
static size_t dir_entries(const char*r,const char*rel){char*p=test_path(r,rel);DIR*d=p?opendir(p):NULL;size_t n=0;if(d){struct dirent*e;while((e=readdir(d)))if(strcmp(e->d_name,".")&&strcmp(e->d_name,".."))n++;closedir(d);}free(p);return n;}
static bool write_stream(const char*p,size_t n,uint32_t seed){int fd=open(p,O_CREAT|O_TRUNC|O_WRONLY|O_CLOEXEC,0644);if(fd<0)return false;uint8_t b[65536];uint32_t x=seed;size_t off=0;while(off<n){size_t z=n-off<sizeof b?n-off:sizeof b;for(size_t i=0;i<z;i++){x^=x<<13;x^=x>>17;x^=x<<5;b[i]=(uint8_t)(x>>24);}if(darc_write_all(fd,b,z)){close(fd);return false;}off+=z;}return close(fd)==0;}
static bool cfix(CFix*f,const char*name,bool multichunk){memset(f,0,sizeof* f);f->d=test_case_dir(name);f->repo=test_path(f->d,"repo");f->src=test_path(f->d,"src");f->file=test_path(f->src,"base");if(!f->d||!f->repo||!f->src||!f->file||test_mkdir(f->src)||test_write(f->file,"base",4,0644))return false;TestProc x=cr_init(f->repo);bool ok=x.code==0;test_proc_free(&x);if(!ok)return false;x=cr_snap_env(f->repo,f->src,"1000",NULL);ok=x.code==0;test_proc_free(&x);if(!ok||test_head(f->repo,f->old))return false;char*n=test_path(f->src,"new.bin");ok=n&&(multichunk?write_stream(n,1600000,0x13579bdu):test_write(n,"new-content",11,0644)==0);free(n);f->refs=refs_count(f->repo);f->objs=test_count_objects(f->repo,0);return ok;}
static void cfree(CFix*f){free(f->file);free(f->src);free(f->repo);free(f->d);memset(f,0,sizeof* f);}
static bool old_head(const CFix*f){char h[65];return !test_head(f->repo,h)&&!strcmp(h,f->old);}
static bool healthy_after_recovery(const char*r){TestProc x=cr_index(r);bool a=x.code==0;test_proc_free(&x);x=cr_verify(r,false);bool b=x.code==0;test_proc_free(&x);return a&&b;}

typedef struct{char*d,*repo,*src,*oldid;} GFix;
static bool gfix(GFix*g,const char*name){memset(g,0,sizeof* g);g->d=test_case_dir(name);g->repo=test_path(g->d,"repo");g->src=test_path(g->d,"src");if(!g->d||!g->repo||!g->src||test_mkdir(g->src))return false;for(int i=0;i<8;i++){char nm[16];snprintf(nm,sizeof nm,"f%d",i);char*p=test_path(g->src,nm);bool ok=p&&write_stream(p,8192,(uint32_t)(0x4400+i*31));free(p);if(!ok)return false;}TestProc x=cr_init(g->repo);bool ok=x.code==0;test_proc_free(&x);if(!ok)return false;x=cr_snap_env(g->repo,g->src,"1000",NULL);ok=x.code==0;test_proc_free(&x);if(!ok)return false;char old[65];if(test_head(g->repo,old))return false;g->oldid=strdup(old);char*p=test_path(g->src,"f0");if(!p||unlink(p)){free(p);return false;}free(p);x=cr_snap_env(g->repo,g->src,"2000",NULL);ok=x.code==0;test_proc_free(&x);if(!ok)return false;x=cr_del(g->repo,g->oldid);ok=x.code==0;test_proc_free(&x);return ok;}
static void gfree(GFix*g){free(g->oldid);free(g->src);free(g->repo);free(g->d);memset(g,0,sizeof* g);}
static bool restore_head_matches(const GFix*g){char*out=test_path(g->d,"out");const char*a[]={"./darc","--repo",g->repo,"restore","HEAD","--to",out,NULL};TestProc x=test_exec(a,NULL);bool ok=x.code==0;test_proc_free(&x);char*rd=test_path(out,"src");ok=ok&&rd&&test_tree_eq(g->src,rd,false);free(rd);free(out);return ok;}
static pid_t hold_lock(const char*r,int*releasefd){int ready[2],rel[2];if(pipe(ready)||pipe(rel))return -1;pid_t p=fork();if(p==0){close(ready[0]);close(rel[1]);int fd=-1;int rc=darc_lock_acquire(r,&fd);char z=rc?0:1;(void)write(ready[1],&z,1);close(ready[1]);if(!rc){(void)read(rel[0],&z,1);darc_lock_release(r,fd);}close(rel[0]);_exit(rc?1:0);}close(ready[1]);close(rel[0]);char z=0;if(read(ready[0],&z,1)!=1||z!=1){close(ready[0]);close(rel[1]);waitpid(p,NULL,0);return -1;}close(ready[0]);*releasefd=rel[1];return p;}

