 if(cfix(&f,"crs010",false)){snprintf(ev,sizeof ev,"DARC_TEST_FAIL_OBJECT_FSYNC=1");x=cr_snap_env(f.repo,f.src,"2000",env);bool ok=x.code==5&&refs_count(f.repo)==f.refs&&old_head(&f);test_proc_free(&x);ok=ok&&healthy_after_recovery(f.repo);test_check("CRS-010",ok,"object fsync failure prevents publication of snapshot ref and preserves old repo");cfree(&f);}else test_check("CRS-010",false,"fixture");
