 if(cfix(&f,"crs012",true)){snprintf(ev,sizeof ev,"DARC_TEST_ENOSPC_BEFORE_REF=1");x=cr_snap_env(f.repo,f.src,"2000",env);bool ok=x.code==5&&refs_count(f.repo)==f.refs&&old_head(&f)&&test_contains(x.err,"No space");test_proc_free(&x);ok=ok&&healthy_after_recovery(f.repo);test_check("CRS-012",ok,"ENOSPC after objects but before ref returns I/O and old snapshot publication stays valid");cfree(&f);}else test_check("CRS-012",false,"fixture");
 {char*d=test_case_dir("crs013"),*cfg=test_path(d,"c.json");test_write(cfg,"{}\n",3,0644);const char*a[]={"./darc","config","validate",cfg,NULL};const char*en[]={"DARC_FAULT_ALLOC_N=96",NULL};x=test_exec(a,en);test_check("CRS-013",x.code==2&&x.code<128&&test_contains(x.err,"E_CONFIG_PARSE"),"allocation #96 fails inside JSON parser and returns cleanly without crash");test_proc_free(&x);free(cfg);free(d);}
